import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function App() {
  const [name, setName] = useState('');
  const [greeting, setGreeting] = useState('');

  const handleSubmit = () => {
    setGreeting('Hello, ' + name + '!');
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        id="name"
        value={name}
        onChange={(e) => setName(e.target.value)}
        placeholder="Your name"
      />
      <button type="submit" id="submit">Submit</button>
      {greeting && <p id="result">{greeting}</p>}
    </form>
  );
}

export default App;

