import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Page Reload', () => {
  test('onSubmit calls preventDefault', async () => {
    const { container: root } = render(<App />);
    const form = root.querySelector('form');
if (!form) throw new Error('No <form> found');
const ev = new Event('submit', { cancelable: true, bubbles: true });
form.dispatchEvent(ev);
await tick();
if (!ev.defaultPrevented)
  throw new Error('Submit handler must call e.preventDefault() to stop the page reload');
  });

  test('Greeting appears after submit', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#name');
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
setter.call(input, 'Aanya');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
const form = root.querySelector('form');
const ev = new Event('submit', { cancelable: true, bubbles: true });
form.dispatchEvent(ev);
await tick();
const result = root.querySelector('#result');
if (!result) throw new Error('Expected #result after submit');
if (!result.textContent.includes('Hello, Aanya'))
  throw new Error('Greeting should include "Hello, Aanya"');
  });
});
